    "självrättning": true,
    "niva": "E",
    "poang": "1/0/0",
    "t": "<p>Beräkna \\((20-8)\\div2^2+5\\).</p>",
    "s": "<p>\\((20-8)\\div2^2+5=12\\div4+5=8\\)</p>",
    "familj": "Räkna med prioriteringsregler",
    "svarstyp": "numeriskt",
