    "svarFormat": "numeriskt",
    "svarEnhet": "cm",
    "ledtrad": "<p>Skriv båda areorna som uttryck i bredden b och utveckla parenteserna.</p>",
    "traningsniva": 4,
    "arbetsinsats": 2,
    "spel": true
