    "svarstyp": "numeriskt",
    "rättSvar": 4.7,
    "självrättning": true,
    "tolerans": 0.2,
    "svarFormat": "numeriskt",
    "svarEnhet": "min",
    "traningsniva": 3,
    "spel": true
