    "svarstyp": "val",
    "rättSvar": "A",
    "tolerans": null,
    "självrättning": true,
    "formaga": [
      "begrepp"
    ],
    "svarFormat": "kort_text",
    "ledtrad": "<p>”Exakt på en rät linje” säger något om styrkan, medan ”stigande” säger något om riktningen.</p>",
