    "formaga": [
      "procedur",
      "begrepp"
    ],
    "ledtrad": "<p>Förväntat antal = antal försök · sannolikhet. Här är sannolikheten den okända faktorn.</p>",
    "traningsniva": 2,
    "arbetsinsats": 1,
    "spel": true
